const code=decodeURIComponent(acceptOfferAction[1]).toUpperCase(),orders=await read('orders'),o=orders.find(x=>x.code===code&&x.userId===user.id);
if(!o)return json(res,404,{error:'Sifariş tapılmadı.'});if(o.selectedOffer)return json(res,409,{error:'Bu sifariş üçün usta artıq seçilib.'});
if(['Tamamlandı','Ləğv edildi'].includes(o.status))return json(res,409,{error:'Bağlanmış sifarişdə təklif seçmək olmaz.'});
