o.selectedOffer={offerId:offer.id,providerId:provider.id,providerName:provider.name,price:Number(offer.price),planId:plan.id,planName:plan.name};o.agreedPrice=Number(offer.price);o.commissionPlan=plan.id;o.commissionRate=Number(plan.rate);o.commissionAmount=commissionFor(o.agreedPrice,o.commissionRate,cfg.minCommission);o.paymentStatus='Gözləyir';o.completionStatus='not_started';o.status='İş razılaşdırılıb';await save('orders',orders);
