if(!adminOK(req))return json(res,401,{error:'Admin icazəsi tələb olunur.'});const orders=await read('orders');return json(res,200,{orders:orders.slice().sort((a,b)=>b.createdAtISO.localeCompare(a.createdAtISO)).map(publicOrder)});
