if(!['Gözləyir','Ödənilib','Güzəşt edilib','Mübahisə'].includes(d.paymentStatus))return json(res,400,{error:'Ödəniş statusu düzgün deyil.'});
const code=decodeURIComponent(payAction[1]).toUpperCase(),orders=await read('orders'),o=orders.find(x=>x.code===code);if(!o)return json(res,404,{error:'Sifariş tapılmadı.'});
if(!o.commissionAmount||o.status!=='Tamamlandı')return json(res,409,{error:'Komissiya yalnız təsdiqlənmiş tamamlanmış sifariş üçün qeyd olunur.'});
o.paymentStatus=d.paymentStatus;o.paidAt=d.paymentStatus==='Ödənilib'?new Date().toISOString():null;o.paidMethod=d.paymentStatus==='Ödənilib'?'manual_admin_confirmation':null;await save('orders',orders);return json(res,200,{ok:true,paymentStatus:o.paymentStatus});
