if(o.status!=='İş tamamlanması gözlənilir')return json(res,409,{error:'Admin təsdiqi üçün gözləyən tamamlanma yoxdur.'});
o.status='Tamamlandı';o.completionStatus='admin_confirmed';o.completionConfirmedAt=new Date().toISOString();await save('orders',orders);return json(res,200,{ok:true,status:o.status});
